param([Parameter(Mandatory=$true)][string]$SupervisorExe)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Assert([bool]$c,[string]$m){if(-not$c){throw $m}}
function Wait-File([string]$p,[int]$s=20){$d=[DateTime]::UtcNow.AddSeconds($s);while([DateTime]::UtcNow-lt$d){if(Test-Path -LiteralPath $p -PathType Leaf){return};Start-Sleep -Milliseconds 150};throw "Timed out: $p"}
function Wait-AclReady([string]$p,[int]$s=20){$d=[DateTime]::UtcNow.AddSeconds($s);while([DateTime]::UtcNow-lt$d){if(Test-Path -LiteralPath $p){try{$e=Get-Content -LiteralPath $p -Raw|ConvertFrom-Json;if(([string]$e.state-eq'ready')-and[bool]$e.descriptor_read_granted){return $e}}catch{}};Start-Sleep -Milliseconds 100};throw "ACL evidence did not reconcile: $(if(Test-Path $p){Get-Content $p -Raw}else{'<missing>'})"}
function Stop-P($p){if($p){try{if(-not$p.HasExited){Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue;$p.WaitForExit(5000)|Out-Null}}catch{}}}
function SignedGet([string]$base,[string]$keyPath,[string]$path){$key=[Convert]::FromBase64String((Get-Content $keyPath -Raw).Trim());$ts=[DateTimeOffset]::UtcNow.ToString('O',[Globalization.CultureInfo]::InvariantCulture);$nonce=[guid]::NewGuid().ToString('N');$bh='e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';$canon="GET`n$path`n1.0`n$ts`n$nonce`n$bh";$h=[Security.Cryptography.HMACSHA256]::new($key);try{$sig=[Convert]::ToHexString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($canon))).ToLowerInvariant()}finally{$h.Dispose()};$headers=@{'X-Sokna-Maintenance-Protocol'='1.0';'X-Sokna-Timestamp'=$ts;'X-Sokna-Nonce'=$nonce;'X-Sokna-Key-Id'='web-adapter';'X-Sokna-Body-SHA256'=$bh;'X-Sokna-Signature'=$sig};Invoke-WebRequest -Uri ($base.TrimEnd('/')+$path) -Method Get -Headers $headers -SkipHttpErrorCheck -TimeoutSec 8}
function AllowedSids([string]$p){@((Get-Acl -LiteralPath $p).Access|Where-Object AccessControlType -eq Allow|ForEach-Object{$_.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value})}
function Assert-MinimalAcl([string]$p){$s=AllowedSids $p;foreach($bad in @('S-1-1-0','S-1-5-11','S-1-5-32-545','S-1-5-32-546')){Assert(-not($s-contains$bad))"Broad SID $bad has access to $p"}}
function Delete-ServiceFixture([string]$name){$svc=Get-Service $name -ErrorAction SilentlyContinue;if($svc){try{if($svc.Status-ne'Stopped'){Stop-Service $name -Force -ErrorAction SilentlyContinue}}catch{};$svc.Dispose()};& sc.exe delete $name *> $null;for($i=0;$i-lt40;$i++){if(-not(Get-Service $name -ErrorAction SilentlyContinue)){break};Start-Sleep -Milliseconds 250}}

$SupervisorExe=(Resolve-Path $SupervisorExe).Path;$serviceName='SoknaApache';Assert($null-eq(Get-Service $serviceName -ErrorAction SilentlyContinue))'SoknaApache already exists on runner.'
$root=Join-Path $env:RUNNER_TEMP ('sokna-p2b-p1a-'+[guid]::NewGuid().ToString('N'));$bin=Join-Path $root 'fake\Apache24\bin';New-Item -ItemType Directory -Path $bin -Force|Out-Null;$httpd=Join-Path $bin 'httpd.exe';Copy-Item "$env:SystemRoot\System32\cmd.exe" $httpd;$image='"'+$httpd+'" -k runservice -n "SoknaApache"';$p=$null
try{
  New-Service -Name $serviceName -BinaryPathName $image -DisplayName 'SOKNA Apache Identity Fixture' -StartupType Manual|Out-Null
  $obj=[string](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\SoknaApache' -Name ObjectName).ObjectName;Assert($obj-eq'LocalSystem')"Expected supported default LocalSystem identity; got $obj"
  $p=Start-Process $SupervisorExe -ArgumentList @('--data-root',$root,'--port','17633') -PassThru -WindowStyle Hidden
  $aclPath=Join-Path $root 'web-adapter-acl.json';$descriptor=Join-Path $root 'control-plane.json';Wait-File $aclPath;Wait-File $descriptor;$e=Wait-AclReady $aclPath
  Assert([string]$e.service_name-eq'SoknaApache')'Service name mismatch';Assert([string]$e.service_account-eq'LocalSystem')'Service account mismatch';Assert([string]$e.service_sid-eq'S-1-5-18')'SYSTEM SID mismatch';Assert([string]$e.php_execution_contract-eq'mod_php_in_soknaapache_service_token')'PHP execution contract mismatch';Assert([string]$e.key_acl_mode-eq'existing_system_acl')'ACL mode mismatch';Assert([bool]$e.exact_identity_read_granted)'Identity access not qualified';Assert([bool]$e.descriptor_read_granted)'Descriptor access not qualified';Assert(-not[bool]$e.broad_read_granted)'Broad read recorded'
  $webKey=Join-Path $root 'secrets\web-adapter.key';$recoveryKey=Join-Path $root 'secrets\recovery-console.key';foreach($x in @($webKey,$recoveryKey,$descriptor)){Assert-MinimalAcl $x};foreach($x in @($webKey,$recoveryKey)){ $s=AllowedSids $x;Assert($s-contains'S-1-5-18')"SYSTEM missing: $x";Assert($s-contains'S-1-5-32-544')"Administrators missing: $x" }
  $base='http://127.0.0.1:17633/';foreach($route in @('/v1/health','/v1/status','/v1/components','/v1/operations/active','/v1/backups','/v1/recovery','/v1/journal/head')){$r=SignedGet $base $webKey $route;Assert([int]$r.StatusCode-eq200)"Signed route failed [$route]: $($r.Content)"}
  Stop-P $p;$p=$null;$p=Start-Process $SupervisorExe -ArgumentList @('--data-root',$root,'--port','17633') -PassThru -WindowStyle Hidden;Wait-File $descriptor;$e2=Wait-AclReady $aclPath;Assert([bool]$e2.descriptor_read_granted)'Restart descriptor reconciliation failed';$r=SignedGet $base $webKey '/v1/health';Assert([int]$r.StatusCode-eq200)'HMAC failed after Supervisor restart'
}finally{Stop-P $p;Delete-ServiceFixture $serviceName}

# Fail-closed behavior for an unqualified shared account. CI evidence only.
$pendingRoot=Join-Path $env:RUNNER_TEMP ('sokna-p2b-p1a-pending-'+[guid]::NewGuid().ToString('N'));$bin=Join-Path $pendingRoot 'fake\Apache24\bin';New-Item -ItemType Directory -Path $bin -Force|Out-Null;$httpd=Join-Path $bin 'httpd.exe';Copy-Item "$env:SystemRoot\System32\cmd.exe" $httpd;$p=$null
try{New-Service -Name $serviceName -BinaryPathName ('"'+$httpd+'" -k runservice') -DisplayName 'SOKNA Apache Pending Fixture' -StartupType Manual|Out-Null;Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\SoknaApache' -Name ObjectName -Value 'NT AUTHORITY\LocalService';$p=Start-Process $SupervisorExe -ArgumentList @('--data-root',$pendingRoot,'--port','17634') -PassThru -WindowStyle Hidden;$a=Join-Path $pendingRoot 'web-adapter-acl.json';Wait-File $a;$pe=Get-Content $a -Raw|ConvertFrom-Json;Assert([string]$pe.state-eq'acl_pending')'Shared LocalService identity did not fail closed';Assert(-not[bool]$pe.exact_identity_read_granted)'Shared LocalService received key authority'}finally{Stop-P $p;Delete-ServiceFixture $serviceName}

